const body = $json.body || $json;
const userText = String(body.mensaje || '').trim();
const eosText = String(body.respuesta || '').trim();
const userId = String(body.usuario_id || '').trim();
if (!userId || !userText || !eosText) return [];
const decisionPattern = /\b(decid|eleg|aprobad|confirm|vamos a|voy a|haremos|implement|cambiar|contratar|invertir|lanzar|cancelar|priorizar|acordamos)\w*/i;
if (!decisionPattern.test(userText + ' ' + eosText)) return [];
return { json: { usuario_id: userId, conversacion_id: body.conversacion_id || null, mensaje: userText.slice(0, 4000), respuesta: eosText.slice(0, 5000), request_id: body.request_id || null } };

