const source = $('01 F6 Detectar candidato').item.json;
const collect = (v) => typeof v === 'string' ? v : Array.isArray(v) ? v.map(collect).filter(Boolean).join('\n') : v && typeof v === 'object' ? collect(v.text || v.output_text || v.content || v.message || v.output || v.response || '') : '';
const raw = collect($json).replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
const start = raw.indexOf('{'); const end = raw.lastIndexOf('}');
if (start < 0 || end <= start) return [];
let parsed; try { parsed = JSON.parse(raw.slice(start, end + 1)); } catch { return []; }
const confidence = Math.max(0, Math.min(1, Number(parsed.confianza || 0)));
const text = (v, max) => String(v || '').trim().slice(0, max);
const title = text(parsed.titulo, 180); const decision = text(parsed.decision, 3000);
if (parsed.es_decision !== true || confidence < 0.72 || !title || !decision) return [];
return { json: { usuario_id: source.usuario_id, conversacion_id: source.conversacion_id, request_id: source.request_id, titulo: title, decision, contexto: text(parsed.contexto, 4000) || null, razon: text(parsed.razon, 4000) || null, resultado_esperado: text(parsed.resultado_esperado, 3000) || null, confianza: confidence, fuente: 'n8n-conversation-v6', metadata: { prompt_version: 'decision-capture-v6', execution_id: String($execution.id || '') } } };

